const raw = $input.first().json;
const arr = Array.isArray(raw) ? raw : [];
// First element is RemoteOK legal notice, skip it
const jobs = arr.length > 0 && arr[0].legal ? arr.slice(1) : arr;
const today = new Date().toISOString();

return jobs.map(j => ({
  json: {
    job_id: `remoteok_${j.id}`,
    job_title: j.position || '',
