// Wellfound returns HTML; try to extract JSON-LD or structured data
const raw = $input.first().json;
const today = new Date().toISOString();

// If response is a string (HTML), extract job data from JSON-LD
let jobs = [];
try {
  if (typeof raw === 'string') {
    const jsonLdMatches = raw.match(/<script type="application\/ld\+json">[\s\S]*?<\/script>/g) || [];
    for (const match of jsonLdMatches) {
      const json = JSON.parse(match.replace(/<script[^>]*>/g, '').replace(/<\/script>/g, '').trim());
      if (json['@type'] === 'JobPosting') jobs.push(json);
      else if (Array.isArray(json['@graph'])) {
        jobs.push(...json['@graph'].filter(i => i['@type'] === 'JobPosting'));
      }
    }
  } else if (Array.isArray(raw)) {
    jobs = raw;
  } else if (raw && raw.jobs) {
    jobs = raw.jobs;
  }
} catch(e) {
  return [{ json: { job_id: 'wellfound_error', job_title: 'Parse error', company: '', job_url: '', source: 'Wellfound', location_text: '', salary: '', description: '', posted_date: '', tags: '', date_found: today } }];
}

if (jobs.length === 0) return [];

return jobs.map((j, i) => ({
  json: {
    job_id: `wellfound_${j.identifier || i}`,
    job_title: j.title || j.name || '',
    company: (j.hiringOrganization && j.hiringOrganization.name) ? j.hiringOrganization.name : '',
    job_url: j.url || '',
    source: 'Wellfound',
    location_text: j.jobLocationType === 'TELECOMMUTE' ? 'Remote' : (j.jobLocation && j.jobLocation.address) || 'Remote',
    salary: j.baseSalary ? `${j.baseSalary.currency} ${j.baseSalary.value && j.baseSalary.value.minValue} - ${j.baseSalary.value && j.baseSalary.value.maxValue}` : '',
    description: (j.description || '').replace(/<[^>]+>/g, ' ').substring(0, 3000),
    posted_date: j.datePosted || '',
    tags: Array.isArray(j.skills) ? j.skills.join(', ') : '',
    date_found: today
  }
}));

