const titleKeywords = [
  'data analyst', 'data scientist', 'business intelligence', 'bi analyst',
  'marketing analyst', 'growth analyst', 'ai marketing', 'performance marketing',
  'martech', 'marketing analytics', 'machine learning', 'analytics engineer',
  'data strategist', 'ai automation', 'ai workflow', 'automation specialist',
  'creative strategist', 'digital marketing analyst', 'growth hacker',
  'seo analyst', 'ppc analyst', 'paid media analyst'
];

const locationKeywords = [
  'async remote', 'asynchronous remote', 'worldwide remote', 'global remote',
  'work from anywhere', 'fully remote', '100% remote', 'remote first',
  'distributed team', 'all timezones', 'apac', 'international'
];

const items = $input.all();

return items.filter(item => {
  const title = (item.json.job_title || '').toLowerCase();
  const desc = (item.json.description || '').toLowerCase();
  const tags = (item.json.tags || '').toLowerCase();
  const loc = (item.json.location_text || '').toLowerCase();
  const allText = `${title} ${desc} ${tags} ${loc}`;

  const titleMatch = titleKeywords.some(kw => title.includes(kw));
  const locationMatch = locationKeywords.some(kw => allText.includes(kw));
  const descMatch = titleKeywords.some(kw => desc.includes(kw));

  return titleMatch || locationMatch || descMatch;
});

// New jobs come from Keyword Filter (via $('Keyword Filter'))
// Existing jobs come from Google Sheets read
const existingItems = $('Get Existing Jobs from Sheet').all();
const existingUrls = new Set(existingItems.map(i => i.json.job_url).filter(Boolean));
const existingKeys = new Set(
  existingItems.map(i => `${(i.json.company || '').toLowerCase()}::${(i.json.job_title || '').toLowerCase()}`).filter(Boolean)
);

const newJobs = $('Keyword Filter').all();

return newJobs.filter(item => {
  const url = item.json.job_url || '';
  const key = `${(item.json.company || '').toLowerCase()}::${(item.json.job_title || '').toLowerCase()}`;
  return !existingUrls.has(url) && !existingKeys.has(key);
});

const REJECT = [
  /\bus[\s-]?only\b/i,
  /\busa[\s-]?only\b/i,
  /united states only/i,
  /\bcanada[\s-]?only\b/i,
  /\buk[\s-]?only\b/i,
  /\beu[\s-]?only\b/i,
  /\beurope[\s-]?only\b/i,
  /\baustralia[\s-]?only\b/i,
  /must be (based|located|residing|living) in (the )?(us|usa|united states|uk|united kingdom|eu|europe|canada|australia)/i,
  /must (be authorized|have authorization|have work authorization) to work in/i,
  /requires? (us|uk|eu) (citizenship|residency|work permit|work authorization)/i,
  /\bhybrid\b/i,
  /\bonsite\b/i,
  /\bon-site\b/i,
  /office (required|only|based)/i,
  /in-(office|person) (required|only)/i,
  /remote (within|inside|only in) (the )?(us|usa|uk|eu|europe|canada|australia)/i,
  /\blatam[\s-]?only\b/i,
  /latin america only/i,
  /\bemea[\s-]?only\b/i,
  /\bw2[\s-]?only\b/i,
  /no (corp.to.corp|c2c|contractors)/i,
  /must work (est|pst|cst|cet) (hours|timezone)/i,
  /fixed (us|eastern|pacific|central|eu) (hours|time)/i
];

const items = $input.all();

return items.map(item => {
  const text = `${item.json.description || ''} ${item.json.location_text || ''} ${item.json.job_title || ''}`;
  const rejected = REJECT.some(p => p.test(text));
  return {
    json: {
      ...item.json,
      hard_filter_passed: !rejected,
      hard_filter_reject_reason: rejected ? 'Country/location restriction detected' : ''
    }
  };
}).filter(item => item.json.hard_filter_passed);

const aiItems = $input.all();
// Pair each AI result with the original job from hard filter
const originalJobs = $('Taiwan Hard Filter').all();

const ASYNC_HIGH = [/\basync\b/i, /\basynchronous\b/i, /\bno meetings?\b/i, /async.first/i];
const ASYNC_MED = [/flexible hours/i, /flexible schedule/i, /set your own hours/i, /outcome.based/i];
const ASYNC_LOW = [/distributed team/i, /remote.first/i, /fully remote/i, /work across time zones/i];

const ASYNC_REJECT = [
  /strict (9.to.5|nine to five)/i,
  /fixed (us|eu|est|pst|cet|gmt) hours/i,
  /daily (standup|live calls|video calls) required/i,
  /must (overlap|be available) (9.5|9am.5pm|full business day)/i
];

return aiItems.map((aiItem, index) => {
  const originalJob = originalJobs[index] ? originalJobs[index].json : {};

  let aiData = {};
  try {
    const content = aiItem.json.choices?.[0]?.message?.content || '{}';
    const cleaned = content.replace(/```json|```/g, '').trim();
    aiData = JSON.parse(cleaned);
  } catch(e) {
    aiData = {
      taiwan_eligible: 'unclear',
      reason: 'AI parse error',
      location_risk: 'medium',
      timezone_risk: 'medium',
      contractor_possible: 'unclear',
      decision: 'manual_check'
    };
  }

  const desc = (originalJob.description || '').toLowerCase();
  const tags = (originalJob.tags || '').toLowerCase();
  const allText = `${desc} ${tags}`;

  let async_level = 'unknown';
  let async_notes = '';

  if (ASYNC_REJECT.some(p => p.test(allText))) {
    async_level = 'sync_required';
    async_notes = 'Fixed hours or required live meetings detected';
  } else if (ASYNC_HIGH.some(p => p.test(allText))) {
    async_level = 'high';
    async_notes = 'Explicitly async or no-meeting culture';
  } else if (ASYNC_MED.some(p => p.test(allText))) {
    async_level = 'medium';
    async_notes = 'Flexible schedule mentioned';
  } else if (ASYNC_LOW.some(p => p.test(allText))) {
    async_level = 'low';
    async_notes = 'Distributed/remote-first but async not explicit';
  } else {
    async_level = 'unknown';
    async_notes = 'Not mentioned';
  }

  return {
    json: {
      ...originalJob,
      taiwan_eligible: aiData.taiwan_eligible || 'unclear',
      taiwan_reason: aiData.reason || '',
      location_risk: aiData.location_risk || 'medium',
      timezone_risk: aiData.timezone_risk || 'medium',
      contractor_possible: aiData.contractor_possible || 'unclear',
      ai_decision: aiData.decision || 'manual_check',
      async_level,
      async_notes
    }
  };
});

const DATA_ROLES = /data (analyst|scientist|engineer|strategist)|business intelligence|\bbi analyst\b|marketing analyst|growth analyst|ai marketing|performance marketing|ai automation|ai workflow|martech analyst|machine learning engineer|analytics engineer|marketing analytics|creative strategist.*data|data.*creative/i;
const ADJ_ROLES = /digital marketing|content strategist|\bseo\b|\bppc\b|paid media|marketing manager|product analyst|operations analyst|growth hacker|crm analyst|email marketing|social media analyst/i;

const WORLDWIDE = /worldwide remote|global remote|work from anywhere|\banywhere\b|international contractor|hires via (deel|remote\.com|oyster)|\beor\b|employer of record|100% remote.*worldwide|all timezones|async.first|no timezone (requirements?|restrictions?)/i;
const APAC = /\bapac\b|asia.pacific|southeast asia|east asia/i;
const ASYNC_HIGH_PAT = /\basync\b|\basynchronous\b|async.first|outcome.based|no meetings?/i;
const ASYNC_MED_PAT = /flexible hours|flexible schedule|set your own hours/i;
const DIST_PAT = /distributed team|remote.first|fully remote/i;

const items = $input.all();

return items.map(item => {
  const j = item.json;
  const title = (j.job_title || '').toLowerCase();
  const desc = (j.description || '').toLowerCase();
  const loc = (j.location_text || '').toLowerCase();
  const tags = (j.tags || '').toLowerCase();
  const sal = (j.salary || '').toLowerCase();
  const allText = `${title} ${desc} ${loc} ${tags}`;

  let score = 0;
  let role_category = 'other';
  let why_good_fit = [];

  // ── Taiwan eligibility (40 pts) ──
  const aiEligible = j.taiwan_eligible;
  if (aiEligible === 'no') {
    score += 0;
    why_good_fit.push('AI flagged as ineligible for Taiwan');
  } else if (WORLDWIDE.test(allText) || aiEligible === 'yes') {
    score += 40;
    why_good_fit.push('Worldwide/global remote — Taiwan eligible');
  } else if (APAC.test(allText)) {
    score += 30;
    why_good_fit.push('APAC-friendly — likely Taiwan eligible');
  } else {
    score += 20;
    why_good_fit.push('No explicit country restriction found');
  }

  // ── Async fit (25 pts) ──
  if (j.async_level === 'sync_required') {
    score += 0;
  } else if (j.async_level === 'high' || ASYNC_HIGH_PAT.test(allText)) {
    score += 25;
    why_good_fit.push('Async-first culture');
  } else if (j.async_level === 'medium' || ASYNC_MED_PAT.test(allText)) {
    score += 20;
    why_good_fit.push('Flexible schedule');
  } else if (DIST_PAT.test(allText)) {
    score += 15;
    why_good_fit.push('Distributed / remote-first team');
  } else {
    score += 10;
  }

  // ── Role fit (25 pts) ──
  if (DATA_ROLES.test(title) || DATA_ROLES.test(tags)) {
    score += 25;
    role_category = 'data_ai_marketing';
    why_good_fit.push('Strong role match: data/AI/marketing analytics');
  } else if (DATA_ROLES.test(desc)) {
    score += 18;
    role_category = 'data_ai_marketing';
    why_good_fit.push('Role skills match in description');
  } else if (ADJ_ROLES.test(title) || ADJ_ROLES.test(tags)) {
    score += 15;
    role_category = 'adjacent';
    why_good_fit.push('Adjacent role — transferable skills apply');
  }

  // ── Salary fit (10 pts base, up to 25) ──
  const salaryNums = sal.match(/\d[\d,]+/g);
  let salaryValue = 0;
  if (salaryNums) {
    const parsed = salaryNums.map(s => parseInt(s.replace(/,/g, ''), 10)).filter(n => n > 100);
    // Detect if annual or monthly: if > 15000 assume annual, divide by 12
    const maxNum = Math.max(...parsed);
    salaryValue = maxNum > 15000 ? Math.round(maxNum / 12) : maxNum;
  }

  if (salaryValue >= 5000) {
    score += 25;
    why_good_fit.push(`Strong salary: ~$${salaryValue}/mo`);
  } else if (salaryValue >= 3000) {
    score += 15;
    why_good_fit.push(`Good salary: ~$${salaryValue}/mo`);
  } else if (j.salary && j.salary.length > 0) {
    score += 10;
    why_good_fit.push('Salary listed');
  }

  score = Math.min(100, Math.max(0, score));

  // Final decision
  let decision;
  if (j.taiwan_eligible === 'no' || j.location_risk === 'high') {
    decision = 'reject';
  } else if (score >= 70 && (j.taiwan_eligible === 'yes' || j.taiwan_eligible === 'unclear')) {
    decision = j.taiwan_eligible === 'unclear' ? 'manual_check' : 'keep';
  } else if (score >= 85 && j.taiwan_eligible === 'yes') {
    decision = 'apply';
  } else if (score < 70) {
    decision = 'reject';
  } else {
    decision = 'manual_check';
  }

  if (score >= 85 && j.taiwan_eligible === 'yes' && j.async_level !== 'sync_required' && j.location_risk !== 'high') {
    decision = 'apply';
  }

  return {
    json: {
      ...j,
      score,
      role_category,
      why_good_fit: why_good_fit.join('. '),
      salary_monthly_est: salaryValue || null,
      decision,
      application_status: '',
      notes: ''
    }
  };
});

const aiItems = $input.all();
const originalJobs = $('Score >= 85 ?').outputData('true') || [];

return aiItems.map((aiItem, i) => {
  const original = (originalJobs[i] && originalJobs[i].json) ? originalJobs[i].json : {};
  const coverLetter = aiItem.json.choices?.[0]?.message?.content || '';
  return {
    json: {
      ...original,
      cover_letter: coverLetter
    }
  };
});

const allItems = $input.all();
const today = new Date().toLocaleDateString('en-US', { timeZone: 'Asia/Taipei', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

// Separate by category
const highScore = allItems.filter(i => i.json.score >= 85 && i.json.taiwan_eligible !== 'no').sort((a, b) => b.json.score - a.json.score);
const midScore = allItems.filter(i => i.json.score >= 70 && i.json.score < 85).sort((a, b) => b.json.score - a.json.score);
const manualCheck = allItems.filter(i => i.json.taiwan_eligible === 'unclear' && i.json.score >= 70);
const rejected = allItems.filter(i => i.json.score < 70 || i.json.taiwan_eligible === 'no');

// Count rejections by reason
const rejectedUS = rejected.filter(i => /(us|usa|united states) only/i.test(i.json.taiwan_reason || '')).length;
const rejectedEU = rejected.filter(i => /(eu|europe|uk) only/i.test(i.json.taiwan_reason || '')).length;
const rejectedHybrid = rejected.filter(i => /hybrid|onsite/i.test(i.json.taiwan_reason || '')).length;
const rejectedTimezone = rejected.filter(i => i.json.timezone_risk === 'high').length;
const rejectedLowScore = rejected.filter(i => i.json.score < 70).length;

// Build top jobs section
const topJobs = [...highScore, ...midScore].slice(0, 10);

const jobLines = topJobs.map((item, idx) => {
  const j = item.json;
  return `${idx + 1}. ${j.job_title}\n   Company: ${j.company}\n   Score: ${j.score}/100\n   Taiwan Eligible: ${j.taiwan_eligible} — ${j.taiwan_reason}\n   Async Level: ${j.async_level}\n   Timezone Risk: ${j.timezone_risk}\n   Salary: ${j.salary || 'Not listed'}\n   Why it fits Jerry: ${j.why_good_fit}\n   Apply: ${j.job_url}`;
}).join('\n\n');

const manualLines = manualCheck.slice(0, 5).map(item => {
  const j = item.json;
  return `• ${j.job_title} at ${j.company} (Score: ${j.score}) — ${j.taiwan_reason} | ${j.job_url}`;
}).join('\n');

const subject = `Daily Taiwan Eligible Async Remote Jobs — ${today} (${topJobs.length} jobs found)`;

const body = `Daily Taiwan Eligible Async Remote Jobs
${'='.repeat(50)}
${today}

SUMMARY
-------
Total fetched today: ${allItems.length}
Passed all filters: ${highScore.length + midScore.length}
High priority (85+): ${highScore.length}
Manual review needed: ${manualCheck.length}
Rejected: ${rejected.length}

${'─'.repeat(50)}
TOP JOBS TODAY
${'─'.repeat(50)}

${jobLines || 'No jobs passed all filters today.'}

${'─'.repeat(50)}
MANUAL CHECK — Taiwan eligibility unclear but score is high
${'─'.repeat(50)}

${manualLines || 'None'}

${'─'.repeat(50)}
REJECTED SUMMARY
${'─'.repeat(50)}
US-only restrictions:      ${rejectedUS}
EU/UK restrictions:        ${rejectedEU}
Hybrid/onsite:             ${rejectedHybrid}
Timezone risk (high):      ${rejectedTimezone}
Score below 70:            ${rejectedLowScore}
